"""Edition sınırını koruyan, paket içi MangaX sürüm notları."""
from __future__ import annotations
from typing import Any
RELEASE_NOTES: dict[str, dict[str, Any]] = {'v0.14.2': {'common': ['Yerel sayfası bulunmayan MyAnimeList kayıtları artık boş çevrimdışı görünüm yerine kullanılabilir çevrimiçi bölüm akışını açıyor.', 'Kütüphane toplu seçiminde görünen mangaların tamamı tek tıkla seçilebiliyor ve açık onaydan sonra birlikte kaldırılabiliyor.']}, 'v0.14.1': {'common': ['MyAnimeList listesinin bütün sayfaları yinelenen kayıt üretmeden eşitleniyor; notlar, koleksiyonlar, yerel dosyalar ve okuma ilerlemesi korunuyor.', 'MAL ve AniList kapak adresleri yalnız güvenilir HTTPS katalog alanlarından kabul edilerek yerel veya şüpheli hedefler engelleniyor.'], 'reader': ['Reader, ortak MyAnimeList senkronizasyonunu korurken Full katalog, Keşfet ve eklenti modüllerini fiziksel olarak içermemeye devam ediyor.']}, 'v0.14.0': {'common': ['Uygulama güncellemeleri artık indirme yüzdesi, anlık hız, kalan süre ve güvenlik doğrulamasını modern MangaX penceresinde gösteriyor.', 'Doğrulanan güncelleme yalnız onayınızla sessiz biçimde kuruluyor; MangaX kapanıp yeni sürümle otomatik yeniden açılıyor.', 'Yarım kalan indirmeler güvenli biçimde sürdürülebiliyor, bozuk dosyalar çalıştırılmıyor ve güncelleme sonucu yeniden açılışta doğrulanıyor.']}, 'v0.13.7': {'common': ['MangaX açılışı hızlandırıldı; pencerenin görünmesi için gerekli olmayan bakım, yedekleme ve arka plan servisleri artık yerel API hazır olduktan sonra başlıyor.', 'Başlangıç zaman çizelgesi güvenli tanılama ölçümleriyle izlenebiliyor; uzak yazı tipi ve ikon stilleri ilk arayüz çizimini bekletmiyor.']}, 'v0.13.6': {'common': ['Kütüphane veritabanı daha güvenli transaction kuralları, otomatik yetim kayıt temizliği ve yoğun kullanımda beklemeyi azaltan SQLite ayarlarıyla güçlendirildi.', 'Büyük kütüphaneler artık manga başına ayrı sorgu çalıştırmadan toplu yükleniyor; uzak ve kullanıcı kaynaklı metinler arayüzde kod olarak çalıştırılmadan güvenli biçimde gösteriliyor.']}, 'v0.13.5': {'common': ["MangaX'in yerel API bağlantısı süreç başına yenilenen güvenli oturum, dar localhost origin kontrolü ve Host doğrulamasıyla güçlendirildi.", 'Başka web sitelerinin MangaX kütüphanesine veya kullanıcı verilerine tarayıcı üzerinden erişmesi engellendi.']}, 'v0.13.4': {'common': ['Kütüphane kartlarına güvenli kaldırma eylemi eklendi; yerel dosyası olan mangalarda silinecek veriler onaydan önce açıkça gösteriliyor.']}, 'v0.13.3': {'common': ['MyAnimeList ve AniList kimlikleri geriye uyumlu dış kimlik alanlarıyla korunuyor.']}, 'v0.13.2': {'common': ['MyAnimeList hesabı bağlı görünmesine rağmen bazı listelerin kütüphaneye hiç aktarılmamasına neden olan Full eşleştirme kaybı düzeltildi.', 'AniList eşleşmesi bulunamayan MAL kayıtları artık güvenli mal_<id> kimliğiyle korunuyor; ağ ve istek sınırı hataları başarısız aşamayı açıkça gösteriyor.']}, 'v0.13.1': {'common': ['MyAnimeList hesap bağlantısında uzun OAuth doğrulama kodlarının reddedilmesine neden olan callback sınırı düzeltildi.', 'Geçerli uzun bağlantı kodları kabul edilirken aşırı büyük istekler güvenli üst sınırla reddedilmeye devam ediyor.']}, 'v0.13.0': {'common': ['MyAnimeList hesabı artık Reader ve Full sürümlerinde hazır uygulama kimliğiyle doğrudan bağlanabiliyor.', 'MAL listesinin otomatik ve isteğe bağlı çift yönlü senkronizasyonu güvenli tarayıcı bağlantısı ve Windows kimlik kasasıyla birlikte sunuluyor.']}, 'v0.12.11': {'common': ['MyAnimeList bağlantısı artık Reader ve Full sürümlerinde hazır uygulama kimliğiyle doğrudan başlatılabiliyor.', 'Bağlantı tarayıcıdaki güvenli OAuth ekranında tamamlanıyor; Client Secret ve hesap tokenları uygulama paketine eklenmiyor.']}, 'v0.12.10': {'common': ['İsteğe bağlı çift yönlü MyAnimeList eşitlemesiyle durum, puan ve okuma ilerlemesi MAL hesabına güvenli biçimde gönderilebiliyor.', 'Bekleyen değişiklikler kalıcı kuyrukta tutuluyor; iki tarafta aynı kayıt değiştiğinde hangi sürümün korunacağı kullanıcıya soruluyor.']}, 'v0.12.9': {'common': ['MyAnimeList otomatik eşitlemesi artık açılışta, 6, 12 veya 24 saatlik aralıklarla çalışacak şekilde ayarlanabiliyor.', 'Yakın zamanda eşitlenen listeler gereksiz yere yeniden istenmiyor; çevrimdışı hatalar açılışı etkilemeden sınırlı biçimde yeniden deneniyor.']}, 'v0.12.8': {'common': ['MyAnimeList entegrasyon ekranı bağlı hesap, son eşitleme, toplam manga ve otomatik eşitleme durumunu tek yerde gösteriyor.', 'Canlı eşitleme ilerlemesi ayrıntılandırıldı; MAL kayıtları kütüphanede sade bir rozetle ayırt edilebiliyor.']}, 'v0.12.7': {'common': ['MyAnimeList hesabı bağlandığında ilk kütüphane eşitlemesi artık otomatik olarak arka planda başlıyor.', 'Entegrasyonlar ekranına canlı aşama, ilerleme, sonuç sayaçları ve güvenli iptal denetimleri eklendi.']}, 'v0.12.6': {'common': ['MyAnimeList manga listesinin tamamını kopya oluşturmadan eşitleyen yeni senkronizasyon altyapısı eklendi.', 'MAL durumu, puanı ve okunan bölüm/cilt bilgileri güncellenirken yerel notlar, koleksiyonlar ve dosyalar korunuyor.']}, 'v0.12.5': {'common': ['MyAnimeList’teki Okuma Planı kayıtları artık kütüphanede ayrı bir durum olarak gösteriliyor.', 'Kütüphane durum filtrelerine anlık seri sayaçları eklendi.']}, 'v0.12.4': {'common': ['Başlangıç sihirbazı artık yalnızca ilk kurulumda gösteriliyor.', 'Güncellemeden sonra yeni özellikleri bir kez gösteren sürüm özeti eklendi.'], 'reader': ['MyAnimeList hesabı ve manga listesi Entegrasyonlar bölümünden yönetilebiliyor.']}}

def release_notes_for(version: str, edition: str) -> dict[str, Any] | None:
    entry = RELEASE_NOTES.get(str(version or '').strip())
    normalized_edition = str(edition or '').strip().lower()
    if not isinstance(entry, dict) or normalized_edition not in {'reader', 'full'}:
        return None
    common = [str(item) for item in entry.get('common', []) if str(item).strip()]
    edition_items = [str(item) for item in entry.get(normalized_edition, []) if str(item).strip()]
    if normalized_edition == 'full':
        raise RuntimeError('Reader çevrimiçi servis içermez.')
        edition_items.extend(full_release_notes_for(version))
    items = [*common, *edition_items]
    if not items:
        return None
    return {'version': version, 'edition': normalized_edition, 'items': items}
